const byId=new Map(rows.map(row=>[row[0],row]));
export const sceneStoryIds=rows.map(row=>row[0]);

// Rate and rhythm are separate selected events. Unspecified cardiac risk stays
// a monitoring cue; it must not become an invented rapid heartbeat. A pulse
// sketch is illustrative and never represents a measured rate or ECG diagnosis.
const responsePulsePatterns:Readonly<Record<string,PulsePattern>>={
  'ivabradine':'slow',
};
const downsidePulsePatterns:Readonly<Record<string,PulsePattern>>={
  'diltiazem':'slow','verapamil':'slow','metoprolol':'slow','atenolol':'slow','bisoprolol':'slow',
  'mixed-amphetamine-salts':'fast','atomoxetine':'fast','albuterol':'fast','hydralazine':'fast','cjc-1295':'fast','mephedrone-4-mmc':'fast',
  'citalopram':'irregular','nortriptyline':'irregular','haloperidol':'irregular','chlorpromazine':'irregular','methadone':'irregular',
  'ranolazine':'irregular','sotalol':'irregular','flecainide':'irregular','levothyroxine':'irregular','ondansetron':'irregular','loperamide':'irregular',
  'azithromycin':'irregular','clarithromycin':'irregular','erythromycin':'irregular','moxifloxacin':'irregular','potassium':'irregular','ibogaine':'irregular',
};

export function getSceneStory(seed:Pick<CatalogSeed,'id'|'scene'|'effects'|'risks'>):SceneStory|undefined{
  const row=byId.get(seed.id);if(!row)return undefined;
  const [,responseAction,responseMode,responseTarget,responseLabel,downsideAction,downsideMode,downsideTarget,downsideLabel,downsideCue]=row;
  return {responseAction,responseMode,responseTarget,responseLabel,responseCue:seed.scene.responseNotes[0],downsideAction,downsideMode,downsideTarget,downsideLabel,downsideCue,
    responsePulsePattern:responseAction==='pulse-check'?(responsePulsePatterns[seed.id]??'monitor'):undefined,
    downsidePulsePattern:downsideAction==='pulse-check'?(downsidePulsePatterns[seed.id]??'monitor'):undefined,
  };
}
